A strongly connected component (SCC) of a directed graph is a maximal set of vertices where each can reach every other. Kosaraju's and Tarjan's algorithms find them in O(V+E). Contracting each SCC to a single node gives a DAG.

```python
def scc(graph):
    order, seen = [], set()
    def dfs(u, g, out):
        seen.add(u)
        for v in g.get(u, []):
            if v not in seen:
                dfs(v, g, out)
        out.append(u)
    for u in graph:
        if u not in seen:
            dfs(u, graph, order)
    rev = {}
    for u in graph:
        for v in graph[u]:
            rev.setdefault(v, []).append(u)
    seen.clear()
    comps = []
    for u in reversed(order):
        if u not in seen:
            c = []
            dfs(u, rev, c)
            comps.append(sorted(c))
    return comps

print(scc({1: [2], 2: [3], 3: [1], 4: [3]}))  # [[4], [1, 2, 3]]
```

A regular method receives the instance (`self`). A `@classmethod` receives the class (`cls`), which is useful for alternative constructors and works correctly with subclasses. A `@staticmethod` receives nothing extra: it is just a function placed in the class namespace.

```python
class Date:
    def __init__(self, y, m, d):
        self.y, self.m, self.d = y, m, d

    @classmethod
    def from_string(cls, text):
        return cls(*map(int, text.split("-")))

    @staticmethod
    def is_leap(year):
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

d = Date.from_string("2026-05-14")
print(d.y, d.m, d.d)        # 2026 5 14
print(Date.is_leap(2024))   # True
```

If a method needs neither the instance nor the class, a plain module-level function is often better.

def insertion_sort(arr):
    for i in range(1, len(arr)):
        key = arr[i]
        j = i - 1
        while j >= 0 and arr[j] > key:
            arr[j + 1] = arr[j]
            j -= 1
        arr[j + 1] = key
    return arr

