Each node stores a value and a pointer to the next node. Keep a `head`; to append, walk to the last node and link the new one there. Appending is O(n) unless you also store a `tail`.

```python
class Node:
    def __init__(self, val):
        self.val = val
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def append(self, val):
        node = Node(val)
        if not self.head:
            self.head = node
            return
        cur = self.head
        while cur.next:
            cur = cur.next
        cur.next = node

    def to_list(self):
        out, cur = [], self.head
        while cur:
            out.append(cur.val)
            cur = cur.next
        return out

ll = LinkedList()
for v in (1, 2, 3):
    ll.append(v)
print(ll.to_list())   # [1, 2, 3]
```

A memoization wrapper can cache results based on function arguments, handling complex cache key scenarios.

```python
from functools import wraps

def memoize_with_args(func):
    cache = {}
    @wraps(func)
    def wrapper(*args, **kwargs):
        # Create cache key from args and kwargs
        key = (args, tuple(sorted(kwargs.items())))
        if key not in cache:
            cache[key] = func(*args, **kwargs)
        return cache[key]
    wrapper.cache = cache
    return wrapper

@memoize_with_args
def expensive(a, b, multiplier=1):
    return (a + b) * multiplier

print(expensive(2, 3))            # 5
print(expensive(2, 3, multiplier=2))  # 10
print(expensive.cache)  # Cache contents
```

