```python
def calculateMinimumHP(dungeon):
    m, n = len(dungeon), len(dungeon[0])
    dp = [[0] * n for _ in range(m)]
    dp[m-1][n-1] = max(1, 1 - dungeon[m-1][n-1])
    for i in range(m-1, -1, -1):
        for j in range(n-1, -1, -1):
            if i == m-1 and j == n-1:
                continue
            if i == m-1:
                dp[i][j] = max(1, dp[i][j+1] - dungeon[i][j])
            elif j == n-1:
                dp[i][j] = max(1, dp[i+1][j] - dungeon[i][j])
            else:
                dp[i][j] = max(1, min(dp[i+1][j], dp[i][j+1]) - dungeon[i][j])
    return dp[0][0]

print(calculateMinimumHP([[-3,5],[-1,-5]]))  # 5
```

The Proxy pattern puts a stand-in object in front of a real one to control access: lazy creation, caching, access checks or logging. The proxy has the same interface, so callers don't notice.

```python
class Database:
    def query(self, sql):
        return f"result of {sql}"

class CachingProxy:
    def __init__(self, db):
        self._db, self._cache = db, {}
    def query(self, sql):
        if sql not in self._cache:
            self._cache[sql] = self._db.query(sql)
        return self._cache[sql]

db = CachingProxy(Database())
print(db.query("SELECT 1"))  # result of SELECT 1
print(db.query("SELECT 1"))  # served from cache
```

