A centroid is a node whose removal leaves every remaining component with at most n/2 nodes. Every tree has one or two centroids. Centroid decomposition repeatedly removes the centroid and recurses, giving a tree of depth O(log n), which helps with path queries and divide-and-conquer.

```python
def centroid(adj, n):
    size = [1] * n
    parent = [-1] * n
    order, stack = [], [0]
    while stack:
        v = stack.pop()
        order.append(v)
        for w in adj[v]:
            if w != parent[v]:
                parent[w] = v
                stack.append(w)
    for v in reversed(order):
        if parent[v] >= 0:
            size[parent[v]] += size[v]
    for v in order:
        biggest = max([n - size[v]] + [size[w] for w in adj[v] if w != parent[v]])
        if biggest <= n // 2:
            return v

adj = [[1], [0, 2], [1, 3], [2, 4], [3]]   # a path of 5 nodes
print(centroid(adj, 5))  # 2
```

def merge_linked_lists(l1, l2):
    dummy = Node(0)
    current = dummy
    while l1 and l2:
        if l1.data <= l2.data:
            current.next = l1
            l1 = l1.next
        else:
            current.next = l2
            l2 = l2.next
        current = current.next
    current.next = l1 if l1 else l2
    return dummy.next

