def knapsack(weights, values, capacity):
    n = len(weights)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for w in range(capacity + 1):
            if weights[i - 1] <= w:
                dp[i][w] = max(values[i - 1] + dp[i - 1][w - weights[i - 1]], dp[i - 1][w])
            else:
                dp[i][w] = dp[i - 1][w]
    return dp[n][capacity]

Use two stacks: one for numbers and one for operators. Apply an operator only when the next operator has equal or lower precedence, and treat parentheses as barriers.

```python
import operator

def evaluate(expr):
    prec = {"+": 1, "-": 1, "*": 2, "/": 2}
    fn = {"+": operator.add, "-": operator.sub, "*": operator.mul, "/": operator.truediv}
    nums, ops = [], []

    def apply():
        b, a = nums.pop(), nums.pop()
        nums.append(fn[ops.pop()](a, b))

    i = 0
    while i < len(expr):
        c = expr[i]
        if c.isdigit() or c == ".":
            j = i
            while j < len(expr) and (expr[j].isdigit() or expr[j] == "."):
                j += 1
            nums.append(float(expr[i:j]))
            i = j
            continue
        if c == "(":
            ops.append(c)
        elif c == ")":
            while ops[-1] != "(":
                apply()
            ops.pop()
        elif c in prec:
            while ops and ops[-1] != "(" and prec[ops[-1]] >= prec[c]:
                apply()
            ops.append(c)
        i += 1
    while ops:
        apply()
    return nums[0]

print(evaluate("3 + 4 * 2"))      # 11.0
print(evaluate("(3 + 4) * 2"))    # 14.0
```

