        self.cache[key] = (value, time.time())

    def clear_expired(self) -> None:
        now = time.time()
        expired = [k for k, (_, ts) in self.cache.items() 
                   if now - ts > self.ttl_seconds]
        for k in expired:
            del self.cache[k]

