```python
# Binary search works with negative numbers
# Key: Maintain sorted order

def binarySearch(arr, target):
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

# Works with negatives
print(binarySearch([-5, -2, 0, 3, 7], -2))  # 1
print(binarySearch([-10, -5, -1, 0, 5], -1))  # 2

# Key insight: Comparison operators work same way
# -5 < -2 < 0 < 3 < 7

# Example: Split array largest sum with negatives
def splitArray(nums, m):
    def can_split(max_sum):
        splits = 1
        current_sum = 0
        for num in nums:
            if current_sum + num > max_sum:
                splits += 1
                current_sum = num
            else:
                current_sum += num
        return splits <= m
    left, right = max(nums), sum(nums)
    while left < right:
        mid = (left + right) // 2
        if can_split(mid):
            right = mid
        else:
            left = mid + 1
    return left

print(splitArray([-1, 4, 4], 3))  # 4
```

