def topo_sort(graph):
    seen, order = set(), []

    def dfs(u):
        seen.add(u)
        for v in graph.get(u, []):
            if v not in seen:
                dfs(v)
        order.append(u)

    for u in graph:
        if u not in seen:
            dfs(u)
    return order[::-1]

