```python
# 0/1 Knapsack: Each item can be used AT MOST ONCE
def knapsack_01(capacity, weights, values):
    dp = [0] * (capacity + 1)
    # Iterate backwards to prevent reusing items
    for i in range(len(weights)):
        for w in range(capacity, weights[i] - 1, -1):
            dp[w] = max(dp[w], values[i] + dp[w - weights[i]])
    return dp[capacity]

print(knapsack_01(5, [2, 3], [3, 4]))  # 7 (one of each)

# Unbounded Knapsack: Each item can be used UNLIMITED TIMES
def knapsack_unbounded(capacity, weights, values):
    dp = [0] * (capacity + 1)
    # Iterate forwards to allow reusing items
    for w in range(capacity + 1):
        for i in range(len(weights)):
            if weights[i] <= w:
                dp[w] = max(dp[w], values[i] + dp[w - weights[i]])
    return dp[capacity]

print(knapsack_unbounded(5, [1, 2], [1, 2]))  # 5 (use small item 5 times)

# Key difference: backward iteration (0/1) vs forward iteration (unbounded)
```

