import heapq
class MedianFinder:
    def __init__(self):
        self.small = []  # max heap
        self.large = []  # min heap
    def addNum(self, num):
        heapq.heappush(self.small, -num)
        if self.small and self.large and -self.small[0] > self.large[0]:
            val = -heapq.heappop(self.small)
            heapq.heappush(self.large, val)
        if len(self.small) > len(self.large) + 1:
            val = -heapq.heappop(self.small)
            heapq.heappush(self.large, val)
        if len(self.large) > len(self.small):
            val = heapq.heappop(self.large)
            heapq.heappush(self.small, -val)
    def findMedian(self):
        if len(self.small) > len(self.large):
            return float(-self.small[0])
        return (-self.small[0] + self.large[0]) / 2

Walk both lists with a pointer each, always attach the smaller node to the result, and append whatever remains at the end. It runs in O(n + m) time and O(1) extra space. A dummy head node avoids special cases.

```python
class ListNode:
    def __init__(self, val=0, next=None):
        self.val, self.next = val, next

def merge(a, b):
    dummy = tail = ListNode()
    while a and b:
        if a.val <= b.val:
            tail.next, a = a, a.next
        else:
            tail.next, b = b, b.next
        tail = tail.next
    tail.next = a or b
    return dummy.next

def build(vals):
    head = None
    for v in reversed(vals):
        head = ListNode(v, head)
    return head

node, out = merge(build([1, 3, 5]), build([2, 4])), []
while node:
    out.append(node.val)
    node = node.next
print(out)  # [1, 2, 3, 4, 5]
```

