An AVL tree is a self-balancing binary search tree. Each node stores a height, and the balance factor (left height minus right height) must stay -1, 0 or 1. When an insert breaks that, rotations restore balance, keeping search, insert and delete at O(log n).

```python
class Node:
    def __init__(self, key):
        self.key, self.left, self.right, self.h = key, None, None, 1

def h(n): return n.h if n else 0
def upd(n): n.h = 1 + max(h(n.left), h(n.right))

def rot_right(y):
    x = y.left; y.left = x.right; x.right = y
    upd(y); upd(x); return x

def rot_left(x):
    y = x.right; x.right = y.left; y.left = x
    upd(x); upd(y); return y

def insert(n, key):
    if not n: return Node(key)
    if key < n.key: n.left = insert(n.left, key)
    else: n.right = insert(n.right, key)
    upd(n)
    b = h(n.left) - h(n.right)
    if b > 1:
        if key > n.left.key: n.left = rot_left(n.left)
        return rot_right(n)
    if b < -1:
        if key < n.right.key: n.right = rot_right(n.right)
        return rot_left(n)
    return n

root = None
for k in range(1, 8):
    root = insert(root, k)
print(root.key, h(root))  # 4 3
```

