A bridge is an edge whose removal disconnects the graph (or increases its number of components). Tarjan's algorithm finds all bridges in O(V + E) with one DFS, tracking each node's discovery time and the lowest discovery time reachable from its subtree. If `low[child] > disc[parent]`, the edge between them is a bridge.

```python
def bridges(n, edges):
    g = [[] for _ in range(n)]
    for u, v in edges:
        g[u].append(v); g[v].append(u)
    disc, low, out, t = [-1] * n, [0] * n, [], [0]
    def dfs(u, parent):
        disc[u] = low[u] = t[0]; t[0] += 1
        for v in g[u]:
            if v == parent:
                continue
            if disc[v] == -1:
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    out.append((u, v))
            else:
                low[u] = min(low[u], disc[v])
    dfs(0, -1)
    return out

print(bridges(4, [(0, 1), (1, 2), (2, 0), (2, 3)]))  # [(2, 3)]
```

```python
def knapsack(capacity, weights, values):
    n = len(weights)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for w in range(capacity + 1):
            if weights[i-1] <= w:
                dp[i][w] = max(values[i-1] + dp[i-1][w-weights[i-1]], dp[i-1][w])
            else:
                dp[i][w] = dp[i-1][w]
    return dp[n][capacity]

print(knapsack(5, [2, 3], [3, 4]))  # 7
