```python
def countPaths(matrix):
    if not matrix or not matrix[0]:
        return 0
    m, n = len(matrix), len(matrix[0])
    memo = {}
    def dfs(i, j, prev):
        if (i, j) in memo:
            return memo[(i, j)]
        count = 1  # Current cell is one path
        for di, dj in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < m and 0 <= nj < n and matrix[ni][nj] > matrix[i][j]:
                count += dfs(ni, nj, matrix[i][j])
        memo[(i, j)] = count
        return count
    result = 0
    for i in range(m):
        for j in range(n):
            result += dfs(i, j, 0)
    return result

print(countPaths([[1, 2], [1, 2]]))  # 6
print(countPaths([[1, 2, 3], [4, 5, 6], [7, 8, 9]]))  # 24

# Time: O(m*n*4^(m*n)) worst, O(m*n) with memoization
# Space: O(m*n) for memo
```

