def longestBitonicSubsequence(arr):
    n = len(arr)
    if n <= 2:
        return n
    # inc[i] = longest increasing subsequence ending at i
    inc = [1] * n
    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + 1)
    # dec[i] = longest decreasing subsequence starting from i
    dec = [1] * n
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                dec[i] = max(dec[i], dec[j] + 1)
    # Longest bitonic: inc[i] + dec[i] - 1 (subtract 1 for peak)
    return max(inc[i] + dec[i] - 1 for i in range(n))

print(longestBitonicSubsequence([1, 5, 2, 3, 4, 2, 1]))  # 6 (1, 5, 4, 2, 1 but 5,4,2,1 works? No. Actually: 1,2,3,4,2,1 = 6)
print(longestBitonicSubsequence([1, 2, 3, 4, 5]))  # 5 (all increasing)
print(longestBitonicSubsequence([5, 4, 3, 2, 1]))  # 5 (all decreasing)

# Time: O(n^2), Space: O(n)
