The load factor of a hash table is the number of stored elements divided by the number of slots (buckets). It measures how full the table is. As it grows, collisions become more likely and lookups slow down, so tables resize and rehash all entries once it passes a threshold, commonly around 0.75 (Java's HashMap) or 2/3 (CPython's dict).

```python
class Table:
    def __init__(self):
        self.slots = [[] for _ in range(4)]
        self.count = 0

    def put(self, key, value):
        if (self.count + 1) / len(self.slots) > 0.75:
            self._grow()
        self.slots[hash(key) % len(self.slots)].append((key, value))
        self.count += 1

    def _grow(self):
        old = [kv for slot in self.slots for kv in slot]
        self.slots = [[] for _ in range(len(self.slots) * 2)]
        for k, v in old:
            self.slots[hash(k) % len(self.slots)].append((k, v))

t = Table()
for i in range(10):
    t.put(i, i)
print(len(t.slots), t.count / len(t.slots))   # 16 0.625
```

