Min-cost max-flow sends as much flow as possible from source to sink at the lowest total cost. The standard method, successive shortest paths, repeatedly finds the cheapest augmenting path in the residual graph (Bellman-Ford handles negative residual costs; Dijkstra with potentials is faster) and pushes flow along it.

```python
def mcmf(n, edges, s, t):
    g = [[] for _ in range(n)]       # edge: [to, cap, cost, rev_index]
    for u, v, cap, cost in edges:
        g[u].append([v, cap, cost, len(g[v])])
        g[v].append([u, 0, -cost, len(g[u]) - 1])
    flow = total = 0
    while True:
        dist = [float("inf")] * n
        dist[s] = 0
        prev = [None] * n
        for _ in range(n):
            for u in range(n):
                for i, (v, cap, cost, _) in enumerate(g[u]):
                    if cap and dist[u] + cost < dist[v]:
                        dist[v], prev[v] = dist[u] + cost, (u, i)
        if dist[t] == float("inf"):
            return flow, total
        f, v = float("inf"), t
        while v != s:
            u, i = prev[v]
            f, v = min(f, g[u][i][1]), u
        v = t
        while v != s:
            u, i = prev[v]
            g[u][i][1] -= f
            g[v][g[u][i][3]][1] += f
            v = u
        flow, total = flow + f, total + f * dist[t]

print(mcmf(4, [(0, 1, 2, 1), (0, 2, 1, 3), (1, 3, 1, 1), (2, 3, 2, 1), (1, 2, 1, 1)], 0, 3))  # (3, 9)
```

