Preorder visits the node first, then its left subtree, then its right subtree. The recursive version is direct; the iterative one uses an explicit stack, pushing the right child first so the left is processed first.

```python
class Node:
    def __init__(self, val, left=None, right=None):
        self.val, self.left, self.right = val, left, right

def preorder(root):
    if not root:
        return []
    return [root.val] + preorder(root.left) + preorder(root.right)

def preorder_iter(root):
    out, stack = [], [root] if root else []
    while stack:
        node = stack.pop()
        out.append(node.val)
        if node.right: stack.append(node.right)
        if node.left: stack.append(node.left)
    return out

tree = Node(1, Node(2, Node(4), Node(5)), Node(3))
