def topological_sort(graph, n):
    visited = [False] * n
    stack = []
    def dfs(node):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor)
        stack.append(node)
    for i in range(n):
        if not visited[i]:
            dfs(i)
    return stack[::-1]

