def binary_search_recursive(arr, target, left=0, right=None):
    if right is None:
        right = len(arr) - 1
    if left > right:
        return -1
    mid = (left + right) // 2
    if arr[mid] == target:
        return mid
    elif arr[mid] < target:
        return binary_search_recursive(arr, target, mid + 1, right)
    else:
        return binary_search_recursive(arr, target, left, mid - 1)

`super()` returns a proxy that looks up methods on the next class in the method resolution order (MRO), so a child can reuse the parent's behavior. It is mostly used in `__init__`.

```python
class Animal:
    def __init__(self, name):
        self.name = name
    def speak(self):
        return f"{self.name} makes a sound"

class Dog(Animal):
    def __init__(self, name, breed):
        super().__init__(name)
        self.breed = breed
    def speak(self):
        return super().speak() + ": woof"

print(Dog("Rex", "Lab").speak())  # Rex makes a sound: woof
```

With multiple inheritance, `super()` follows the MRO (see `Dog.__mro__`) and not just "the parent".

Memoization is caching function results to avoid recomputation. Common patterns include using lru_cache, cache, or implementing manual caching with dictionaries.

```python
from functools import lru_cache

# Manual memoization
def fib_manual(n, memo={}):
    if n in memo:
        return memo[n]
    if n < 2:
        return n
    memo[n] = fib_manual(n-1, memo) + fib_manual(n-2, memo)
    return memo[n]

# Using decorator
@lru_cache(maxsize=None)
def fib_cached(n):
    if n < 2:
        return n
    return fib_cached(n-1) + fib_cached(n-2)
```

