        self.keep = 1
        self.temp = 2

    def __delattr__(self, name):
        if name == "keep":
            raise AttributeError("keep cannot be deleted")
        super().__delattr__(name)

p = Protected()
del p.temp
print(hasattr(p, "temp"))   # False
try:
    del p.keep
except AttributeError as e:
    print(e)                # keep cannot be deleted
```

