def numDistinct(s, t):
    m, n = len(s), len(t)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    # Empty target has one way: select nothing
    for i in range(m + 1):
        dp[i][0] = 1
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s[i-1] == t[j-1]:
                # Either include this char or don't
                dp[i][j] = dp[i-1][j-1] + dp[i-1][j]
            else:
                # Can't use this char, carry forward
                dp[i][j] = dp[i-1][j]
    return dp[m][n]

print(numDistinct('rabbbit', 'rabbit'))  # 3 (rab_b_it, rab_bi_t, rabb_i_t)
print(numDistinct('babgbag', 'bag'))  # 5

# Space-optimized version
def numDistinct_optimized(s, t):
    m, n = len(s), len(t)
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, m + 1):
        for j in range(n, 0, -1):  # Backwards to avoid overwriting
            if s[i-1] == t[j-1]:
                dp[j] += dp[j-1]
    return dp[n]

print(numDistinct_optimized('rabbbit', 'rabbit'))  # 3
```

A logging decorator wraps a function so each call, its arguments, its result and any exception are recorded without changing the function's body. Use `functools.wraps` to keep the original name and docstring.

```python
import logging
from functools import wraps

logging.basicConfig(level=logging.INFO, format="%(levelname)s %(message)s")

def log_calls(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        logging.info("calling %s%r", func.__name__, args)
        try:
            result = func(*args, **kwargs)
        except Exception:
            logging.exception("%s failed", func.__name__)
            raise
        logging.info("%s returned %r", func.__name__, result)
        return result
    return wrapper

@log_calls
def divide(a, b):
    return a / b

divide(10, 2)  # INFO calling divide(10, 2) / INFO divide returned 5.0
```

