from functools import wraps

def cached_with_invalidation(func):
    cache = {}

    def wrapper(*args, **kwargs):
        key = str(args) + str(kwargs)
        if key not in cache:
            cache[key] = func(*args, **kwargs)
        return cache[key]

    def invalidate(*args, **kwargs):
        key = str(args) + str(kwargs)
        if key in cache:
            del cache[key]

