from collections import deque
def zigzag(root):
    if not root:
        return []
    result = []
    q = deque([root])
    left_to_right = True
    while q:
        level_size = len(q)
        level = []
        for _ in range(level_size):
            node = q.popleft()
            level.append(node.val)
            if node.left:
                q.append(node.left)
            if node.right:
                q.append(node.right)
        if not left_to_right:
            level.reverse()
        result.append(level)
        left_to_right = not left_to_right
    return result

To reverse a linked list in groups of k, count k nodes, reverse that segment in place, and link it to the result of recursing on the rest. If fewer than k nodes remain, leave them as they are.

```python
class Node:
    def __init__(self, val, next=None):
        self.val, self.next = val, next


def reverse_k(head, k):
    node, n = head, 0
    while node and n < k:
        node, n = node.next, n + 1
    if n < k:
        return head
    prev, cur = reverse_k(node, k), head
    for _ in range(k):
        cur.next, prev, cur = prev, cur, cur.next
    return prev


head = Node(1, Node(2, Node(3, Node(4, Node(5)))))
node = reverse_k(head, 2)
out = []
while node:
    out.append(node.val)
    node = node.next
print(out)  # [2, 1, 4, 3, 5]
```

